// AWI: REST endpoint testimoni (dipakai n8n/Telegram). Hanya user yang boleh edit_posts.
add_action( 'rest_api_init', function () {
	$can = function () { return current_user_can( 'edit_posts' ); };

	register_rest_route( 'awi/v1', '/testimeta/(?P<id>\d+)', array(
		'methods'             => 'GET',
		'permission_callback' => $can,
		'callback'            => function ( $r ) {
			$id = (int) $r['id'];
			return array( 'id' => $id, 'type' => get_post_type( $id ), 'meta' => get_post_meta( $id ) );
		},
	) );

	// Buat testimoni baru: nama, kota, model, kutipan, photo_id (media WP).
	register_rest_route( 'awi/v1', '/testimoni', array(
		'methods'             => 'POST',
		'permission_callback' => $can,
		'callback'            => function ( $r ) {
			$nama    = sanitize_text_field( (string) $r->get_param( 'nama' ) );
			$kota    = sanitize_text_field( (string) $r->get_param( 'kota' ) );
			$model   = sanitize_text_field( (string) $r->get_param( 'model' ) );
			$kutipan = sanitize_textarea_field( (string) $r->get_param( 'kutipan' ) );
			$photo   = (int) $r->get_param( 'photo_id' );
			if ( '' === $nama || '' === $kota || '' === $model || '' === $kutipan || ! $photo ) {
				return new WP_Error( 'awi_testi_kurang', 'Nama, kota, model, kutipan, dan foto wajib diisi.', array( 'status' => 400 ) );
			}
			$kutipan = trim( $kutipan, " \t\n\r\"“”" );
			$content = 'Serah terima ' . $model . ' — “' . $kutipan . '”';
			$id      = wp_insert_post( array(
				'post_type'    => 'testimoni',
				'post_status'  => 'publish',
				'post_title'   => $nama,
				'post_content' => $content,
				'post_author'  => 6,
			), true );
			if ( is_wp_error( $id ) ) {
				return $id;
			}
			$url = wp_get_attachment_url( $photo );
			update_post_meta( $id, '_nama', $nama );
			update_post_meta( $id, '_kota', $kota );
			update_post_meta( $id, '_rating', 'super' );
			update_post_meta( $id, '_photo', $url );
			set_post_thumbnail( $id, $photo );
			wp_update_post( array(
				'ID'         => $photo,
				'post_title' => 'Serah terima ' . $model . ' – ' . $nama,
			) );
			update_post_meta( $photo, '_wp_attachment_image_alt', 'Serah terima ' . $model . ' ke ' . $nama . ' dari ' . $kota . ' – BYD Haka Karebosi Makassar' );
			do_action( 'litespeed_purge_all' );
			return array( 'id' => $id, 'link' => get_permalink( $id ), 'arsip' => home_url( '/testimoni/' ), 'photo' => $url );
		},
	) );

	// Batalkan: pindahkan ke Sampah (bisa dipulihkan dari WP Admin).
	register_rest_route( 'awi/v1', '/testimoni/(?P<id>\d+)', array(
		'methods'             => 'DELETE',
		'permission_callback' => $can,
		'callback'            => function ( $r ) {
			$id = (int) $r['id'];
			if ( 'testimoni' !== get_post_type( $id ) ) {
				return new WP_Error( 'awi_testi_404', 'Testimoni tidak ditemukan.', array( 'status' => 404 ) );
			}
			$nama = get_the_title( $id );
			wp_trash_post( $id );
			do_action( 'litespeed_purge_all' );
			return array( 'id' => $id, 'nama' => $nama, 'status' => 'trash' );
		},
	) );
} );
